void Solver::bump_var(int var, double coeff) {
    // increase activity of the variable
    double inc = var_inc * coeff;
    activity[var] += inc;

    // prevent overflow by periodic global rescaling
    const double MAX_ACTIVITY = 1e120;
    if (activity[var] > MAX_ACTIVITY) {
        const double SCALE = 1e-120;
        for (int i = 1; i <= vars; ++i) activity[i] *= SCALE;
        var_inc *= SCALE;
    }

    // keep the VSIDS priority queue up‑to‑date
    if (vsids.inHeap(var)) vsids.update(var);
}
